package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.fasterxml.jackson.core.StreamReadFeature;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.ruoyi.medical.contracts.*;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import static com.ruoyi.medical.persistence.FormalEvaluationExecutionProtocol.*;

/** Original SQL ledger inspection. No joined query may silently omit an expected cell or node. */
final class FormalEvaluationExecutionLedger {
 private final JdbcTemplate db;private final PermissionSchema json;private final EvaluationService evaluations;
 private final FormalAgentCandidateAuthority candidates;private final AgentExecutionPolicyAuthority policies;private final ResourceReadAuthority resources;
 private final JsonMapper decoder=JsonMapper.builder().propertyNamingStrategy(com.fasterxml.jackson.databind.PropertyNamingStrategies.SNAKE_CASE).enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES).build();
 FormalEvaluationExecutionLedger(DataSource data,PermissionSchema json,EvaluationService evaluations,FormalAgentCandidateAuthority candidates,AgentExecutionPolicyAuthority policies,ResourceReadAuthority resources){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;this.evaluations=evaluations;this.candidates=candidates;this.policies=policies;this.resources=resources;}
 record Snapshot(String project,String execution,String canonical,List<FormalEvaluationExecutionProtocol.Record> records,JsonNode authorizations){Snapshot{records=List.copyOf(records);authorizations=authorizations.deepCopy();}}
 Snapshot require(EnterpriseAccess.Admission a,String evaluationId,PermissionProtocol.Basis candidate,PermissionProtocol.Basis policy)throws Exception{
  return require(a,evaluationId,candidate,policy,false);
 }
 Snapshot require(EnterpriseAccess.Admission a,String evaluationId,PermissionProtocol.Basis candidate,PermissionProtocol.Basis policy,boolean historical)throws Exception{
  FormalEvaluationExecutionAdmission.current(a);String tenant=a.context().tenant_id();
  // Execution completion precedes scoring/finalization; requiring a finalized score here creates a cycle.
  var definition=evaluations.requireFormalDefinitionMetadata(a,evaluationId);var project=definition.row().projectId();
  var read=resources.require(a,new PermissionProtocol.Scope(tenant,project,"EVALUATION",evaluationId),"evaluation.read","EVALUATION_RESULTS");
  var fixedCandidate=candidates.require(a,candidate,project,"EVALUATION_RESULTS");if(!fixedCandidate.executionPolicy().equals(policy))bad();
  var fixedPolicy=policies.requireHistoricalByVersion(a,policy.version_id(),policy.content_sha256(),project,fixedCandidate.classification(),"EVALUATION_RESULTS");
  var executable=historical?null:policies.requireByVersion(a,policy.version_id(),policy.content_sha256(),project,fixedCandidate.classification(),"RUN_CREATION");
  if(!historical&&"DISABLED".equals(fixedCandidate.status()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
  var row=one(db.queryForList("SELECT * FROM formal_evaluation_execution WHERE tenant_id=? AND evaluation_id=? AND candidate_version=? LIMIT 2",tenant,evaluationId,candidate.version_id()));
  String execution=text(row,"execution_id"),actor=text(row,"created_by");metadata(row,tenant,project,actor);same(tenant,text(row,"tenant_id"));same(project,text(row,"project_id"));same(candidate.content_sha256(),text(row,"candidate_sha256"));same(policy.version_id(),text(row,"policy_version"));same(policy.content_sha256(),text(row,"policy_sha256"));same(definition.row().contentHash(),text(row,"definition_sha256"));same(fixedCandidate.runtimeManifestSha256(),text(row,"runtime_manifest_sha256"));
  String requestJson=text(row,"canonical_request"),admissionJson=text(row,"canonical_admission");same(hash(requestJson),text(row,"request_sha256"));same(hash(admissionJson),text(row,"admission_sha256"));
  var request=decoder.readValue(requestJson,Start.class);if(!request.evaluationId().equals(evaluationId)||!request.candidate().equals(candidate)||!request.executionPolicy().equals(policy)||!request.definitionSha256().equals(definition.row().contentHash()))bad();
  var admission=decoder.readTree(admissionJson);same(json.canonical(admission),admissionJson);same(json.tree(definition.definition()),admission.required("definition"));same(json.tree(request),admission.required("request"));
  var expected=FormalEvaluationExecutionAdmission.matrix(definition.definition(),request,fixedCandidate.runtimeManifestSha256(),fixedPolicy.definition().bindings(),json);same(json.tree(expected),admission.required("nodes"));
  int expectedCells=definition.definition().request().samples().size()*definition.definition().request().variance_policy().repeat_count();if(number(row,"expected_cells")!=expectedCells||number(row,"expected_nodes")!=expected.size())bad();
  var cells=db.queryForList("SELECT * FROM formal_evaluation_cell WHERE tenant_id=? AND execution_id=? ORDER BY sample_id,repeat_index LIMIT 10001",tenant,execution);if(cells.size()!=expectedCells)bad();
  var byCell=new HashMap<String,Cell>();for(var n:expected)byCell.put(cellKey(n.cell()),n.cell());
  var records=new ArrayList<FormalEvaluationExecutionProtocol.Record>();var canonical=json.object();canonical.set("execution",AgentPublicationWitness.tree(row));var capturedCells=canonical.putArray("cells");
  for(var cell:cells){metadata(cell,tenant,project,actor);var actual=decoder.readValue(text(cell,"canonical_cell"),Cell.class);same(hash(text(cell,"canonical_cell")),text(cell,"cell_sha256"));same(actual,byCell.remove(cellKey(actual)));same(project,text(cell,"project_id"));same(tenant,text(cell,"tenant_id"));same(execution,text(cell,"execution_id"));same(actual.sampleId(),text(cell,"sample_id"));if(actual.repeatIndex()!=number(cell,"repeat_index"))bad();same(actual.sourceFamily(),text(cell,"source_family"));same(actual.split(),text(cell,"split"));same(actual.input().version_id(),text(cell,"input_version"));same(actual.input().content_sha256(),text(cell,"input_sha256"));same(actual.expected().version_id(),text(cell,"expected_version"));same(actual.expected().content_sha256(),text(cell,"expected_sha256"));same(actor,text(cell,"created_by"));
   String run=text(cell,"run_id"),principal=text(cell,"principal_id");
   var registry=one(db.queryForList("SELECT * FROM execution_registry WHERE tenant_id=? AND run_id=? LIMIT 2",tenant,run));same("SYSTEM_JOB",text(registry,"execution_kind"));same(project,text(registry,"project_id"));same(actor,text(registry,"created_by"));jsonSame(text(cell,"canonical_scope"),text(registry,"scope_manifest"));
   var p=one(db.queryForList("SELECT * FROM run_principal WHERE tenant_id=? AND principal_id=? AND run_id=? LIMIT 2",tenant,principal,run));same(project,text(p,"project_id"));same(actor,text(p,"initiator_id"));jsonSame(text(cell,"canonical_principal"),text(p,"capability_manifest"));
   var job=one(db.queryForList("SELECT * FROM system_job_run WHERE tenant_id=? AND run_id=? LIMIT 2",tenant,run));same("EVALUATION_VERIFICATION",text(job,"job_type"));same("SYSTEM_JOB",text(job,"execution_kind"));same("EVALUATION",text(job,"target_kind"));same(evaluationId,text(job,"target_id"));same(evaluationId,text(job,"target_revision"));same(candidate.version_id(),text(job,"config_revision"));same(project,text(job,"project_id"));same(actor,text(job,"initiator_id"));same(tenant+"/"+run,text(job,"workflow_id"));same("SUCCEEDED",text(job,"status"));if(job.get("ended_at")==null)unavailable();jsonSame(text(cell,"canonical_input"),text(job,"input_manifest"));same(hash(text(cell,"canonical_input")),text(cell,"input_manifest_sha256"));same(text(cell,"input_manifest_sha256"),text(job,"input_sha256"));
   var nodes=db.queryForList("SELECT * FROM formal_evaluation_node WHERE tenant_id=? AND run_id=? ORDER BY node_kind LIMIT 11",tenant,run);if(nodes.size()!=fixedPolicy.definition().bindings().size())bad();
   var c=json.object();c.set("cell",AgentPublicationWitness.tree(cell));c.set("registry",AgentPublicationWitness.tree(registry));c.set("principal",AgentPublicationWitness.tree(p));c.set("job",AgentPublicationWitness.tree(job));var capturedNodes=c.putArray("nodes");
   for(var node:nodes){metadata(node,tenant,project,actor);same(run,text(node,"run_id"));var n=decoder.readValue(text(node,"canonical_node"),Node.class);same(hash(text(node,"canonical_node")),text(node,"node_sha256"));same(actual,n.cell());same(n.nodeKind(),text(node,"node_kind"));String step=text(node,"step_id");
    boolean deterministic=FormalEvaluationExecutionProtocol.deterministic(n);
    var result=one(db.queryForList("SELECT * FROM "+(deterministic?"formal_evaluation_deterministic_outcome":"formal_evaluation_node_result")+" WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2",tenant,run,step));metadata(result,tenant,project,actor);same(run,text(result,"run_id"));same(step,text(result,"step_id"));var record=decoder.readValue(text(result,"canonical_record"),FormalEvaluationExecutionProtocol.Record.class);same(hash(text(result,"canonical_record")),text(result,"record_sha256"));same(n,record.node());same(run,record.runId());same(step,record.stepId());if(number(result,"lease_generation")!=record.leaseGeneration())bad();
    var s=one(db.queryForList("SELECT * FROM run_step WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2",tenant,run,step));same(project,text(s,"project_id"));same(n.role().version_id(),text(s,"role_version"));same("SUCCEEDED",text(s,"status"));if(number(s,"lease_generation")!=record.leaseGeneration())bad();same(record.inputManifest().sha256(),text(s,"input_sha256"));
    var dispatch=one(db.queryForList("SELECT * FROM formal_evaluation_node_dispatch WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2",tenant,run,step));metadata(dispatch,tenant,project,actor);same(record.inputManifest().artifactId(),text(dispatch,"input_artifact_id"));same(record.inputManifest().sha256(),text(dispatch,"input_sha256"));if(number(dispatch,"lease_generation")!=record.leaseGeneration())bad();
    if(deterministic){same("SUCCEEDED",text(result,"state"));same(record.stepReceiptSha256(),text(result,"receipt_sha256"));same(hash(text(result,"canonical_receipt")),text(result,"receipt_sha256"));}
    Map<String,Object> session=null;
    if(!deterministic){
    session=one(db.queryForList("SELECT * FROM professional_runtime_session WHERE tenant_id=? AND session_id=? AND run_id=? AND step_id=? AND lease_generation=? LIMIT 2",tenant,text(result,"session_id"),run,step,record.leaseGeneration()));metadata(session,tenant,project,actor);same("CLOSED",text(session,"admission_state"));same(record.stepEnvelope().sha256(),text(session,"envelope_sha256"));same(text(s,"input_sha256"),text(session,"input_sha256"));
    var start=decoder.readTree(text(session,"canonical_start"));same(hash(text(session,"canonical_start")),text(session,"start_sha256"));same("EVALUATION_VERIFICATION",start.required("purpose").asText());same(n.nodeKind(),start.required("node_kind").asText());same(text(result,"session_id"),start.required("session_id").asText());
    var sessionBinding=ProfessionalRuntimeObservations.jsonBinding(start.required("binding"));same(tenant,sessionBinding.tenant_id());same(run,sessionBinding.run_id());same(step,sessionBinding.step_id());same(record.leaseGeneration(),sessionBinding.lease_generation());same(text(session,"action_id"),sessionBinding.action_id());same(text(session,"input_sha256"),sessionBinding.input_sha256());same(record.stepEnvelope().sha256(),sessionBinding.step_envelope_sha256());
    }
    // Absence of an independently registered completion is never inferred from HOST_FINISH/process-exited.
    // Professional supervisor closure or private deterministic N03/N06 provenance, business outcomes and actual C07 completion are checked after original-object GET.
    verifyInvocations(tenant,project,record);for(String check:record.checkIds()){var checkRow=one(db.queryForList("SELECT status,invalidation_reason FROM check_run WHERE tenant_id=? AND project_id=? AND check_id=? AND run_id=? AND step_id=? LIMIT 2",tenant,project,check,run,step));same("SUCCEEDED",text(checkRow,"status"));if(checkRow.get("invalidation_reason")!=null)bad();}
    records.add(record);var captured=json.object();captured.set("node",AgentPublicationWitness.tree(node));captured.set("result",AgentPublicationWitness.tree(result));captured.set("step",AgentPublicationWitness.tree(s));captured.set("dispatch",AgentPublicationWitness.tree(dispatch));if(session!=null)captured.set("session",AgentPublicationWitness.tree(session));else captured.put("execution_mode","DETERMINISTIC");capturedNodes.add(captured);
   }capturedCells.add(c);
  }
  if(!byCell.isEmpty())bad();FormalEvaluationCoverage.exact(expected,records);
  var event=event(row,json);var audit=one(db.queryForList("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND audit_id=? AND project_id=? AND subject_id=? AND action='evaluation.execution_prepared' AND result='SUCCESS' LIMIT 2",tenant,text(row,"audit_id"),project,actor));same(event,decoder.readTree(text(audit,"resource_ref")));var emitted=one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND event_type='evaluation.execution_prepared' LIMIT 2",tenant,text(row,"event_id"),execution));same(event,decoder.readTree(text(emitted,"payload")));
  var authorizations=json.object();authorizations.set("evaluation_read",AgentPublicationWitness.tree(read));authorizations.set("candidate",fixedCandidate.authorizations());authorizations.set("policy",fixedPolicy.authorizations());canonical.set("authorizations",authorizations);
  definition.requireUnchanged();fixedCandidate.requireUnchanged();fixedPolicy.requireUnchanged();if(executable!=null)executable.requireUnchanged();return new Snapshot(project,execution,json.canonical(canonical),records,authorizations);
 }
 private void verifyInvocations(String tenant,String project,FormalEvaluationExecutionProtocol.Record record)throws Exception{
  var all=db.queryForList("SELECT invocation_id,action_id,lease_generation FROM invocation WHERE tenant_id=? AND run_id=? AND step_id=? ORDER BY invocation_id LIMIT 1001",tenant,record.runId(),record.stepId());if(all.size()!=record.invocations().size())bad();var ids=new HashSet<String>();for(var row:all)ids.add(text(row,"invocation_id"));
  for(var invocation:record.invocations()){
   if(!ids.remove(invocation.invocationId()))bad();var i=one(db.queryForList("SELECT * FROM invocation WHERE tenant_id=? AND invocation_id=? AND project_id=? AND run_id=? AND step_id=? AND action_id=? LIMIT 2",tenant,invocation.invocationId(),project,record.runId(),record.stepId(),invocation.actionId()));same("SUCCEEDED",text(i,"status"));same("SETTLED",text(i,"settlement_status"));same(record.node().model().version_id(),text(i,"config_revision"));same(invocation.modelResult().artifactId(),text(i,"result_artifact_id"));same(invocation.modelResult().sha256(),text(i,"result_sha256"));same(invocation.sendManifestSha256(),text(i,"actual_send_sha256"));if(number(i,"lease_generation")!=record.leaseGeneration()||number(i,"dispatch_generation")!=1)bad();
   var action=one(db.queryForList("SELECT invocation_id,lease_generation FROM step_action_binding WHERE tenant_id=? AND run_id=? AND step_id=? AND action_id=? AND kind='MODEL_CALL' LIMIT 2",tenant,record.runId(),record.stepId(),invocation.actionId()));same(invocation.invocationId(),text(action,"invocation_id"));if(number(action,"lease_generation")!=record.leaseGeneration())bad();
   var binding=one(db.queryForList("SELECT request_sha256 FROM formal_invocation_binding WHERE tenant_id=? AND invocation_id=? LIMIT 2",tenant,invocation.invocationId()));same(invocation.requestSha256(),text(binding,"request_sha256"));
   for(var object:Map.of("MODEL_RESULT",invocation.modelResult(),"PROVIDER_CAPTURE",invocation.providerCapture()).entrySet()){var registered=one(db.queryForList("SELECT artifact_id FROM formal_invocation_registered_object WHERE tenant_id=? AND invocation_id=? AND kind=? LIMIT 2",tenant,invocation.invocationId(),object.getKey()));same(object.getValue().artifactId(),text(registered,"artifact_id"));}
   var accounting=one(db.queryForList("SELECT receipt_sha256 FROM formal_invocation_accounting WHERE tenant_id=? AND invocation_id=? LIMIT 2",tenant,invocation.invocationId()));same(invocation.settlementReceiptSha256(),text(accounting,"receipt_sha256"));
  }if(!ids.isEmpty())bad();
 }
 static JsonNode event(Map<String,Object> row,PermissionSchema json){var n=json.object().put("schema_version","1.0.0").put("kind","EVALUATION_EXECUTION_PREPARED");for(String key:List.of("execution_id","evaluation_id","definition_sha256","candidate_version","candidate_sha256","policy_version","policy_sha256","request_sha256","admission_sha256"))n.put(key,text(row,key));n.put("expected_cells",Math.toIntExact(number(row,"expected_cells")));n.put("expected_nodes",Math.toIntExact(number(row,"expected_nodes")));return n;}
 private void metadata(Map<String,Object> row,String tenant,String project,String actor){same(tenant,text(row,"tenant_id"));same(project,text(row,"project_id"));same(actor,text(row,"created_by"));same("1.0.0",text(row,"schema_version"));same(json.manifestSha256(),text(row,"schema_manifest_sha256"));if(row.get("created_at")==null)bad();}
 private void jsonSame(String a,String b)throws Exception{same(decoder.readTree(a),decoder.readTree(b));}
 private static String cellKey(Cell c){return c.sampleId()+":"+c.repeatIndex();}private static String hash(String value){return org.apache.commons.codec.digest.DigestUtils.sha256Hex(value);}
 private static String text(Map<String,Object> row,String key){var v=row.get(key);if(!(v instanceof String))bad();return (String)v;}private static long number(Map<String,Object> row,String key){var v=row.get(key);if(!(v instanceof Number))bad();return ((Number)v).longValue();}
 private static <T>T one(List<T> rows){if(rows.isEmpty())unavailable();if(rows.size()!=1)bad();return rows.get(0);}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}
 private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void unavailable(){throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);}
}
